import random
from app.api.handlers import _parse_formula, _evaluate, _InvalidFormula

random.seed(0)
vars_ = ["id", "n", "1", "2", "7", "0"]
ops = ["+", "-", "*", "//"]

def gen(depth=0):
    r = random.random()
    if depth > 3 or r < 0.35:
        base = random.choice(vars_)
        if random.random() < 0.2:
            return "-" + base
        return base
    if r < 0.5:
        return "(" + gen(depth+1) + ")"
    a, b = gen(depth+1), gen(depth+1)
    op = random.choice(ops)
    return f"{a} {op} {b}"

bad = 0
checked = 0
for _ in range(20000):
    f = gen()
    if len(f) > 60:
        continue
    try:
        tree = _parse_formula(f)
    except _InvalidFormula:
        continue
    for idv, nv in [(1,12),(2,14),(3,12),(0,0),(5,1)]:
        env = {"id": idv, "n": nv}
        try:
            got = _evaluate(tree, env)
        except _InvalidFormula:
            continue
        ref = eval(f, {"__builtins__": {}}, {"id": idv, "n": nv})
        checked += 1
        if got != ref:
            bad += 1
            print("MISMATCH", repr(f), got, ref)
            if bad > 5:
                raise SystemExit
print("checked", checked, "mismatches", bad)
